def second_smallest(numbers):
    """
    Returns the second smallest number in the list.
    Raises a ValueError if there is no second smallest element.
    """
    if not isinstance(numbers, list):
        raise TypeError("Input must be a list.")

    # Remove duplicates to handle cases like [1,1,1]
    unique_numbers = set(numbers)

    if len(unique_numbers) < 2:
        raise ValueError("List must contain at least two distinct elements.")

    smallest = float('inf')
    second = float('inf')

    for num in unique_numbers:
        if num < smallest:
            second = smallest
            smallest = num
        elif smallest < num < second:
            second = num

    return second


